import{_ as r,l as n,o as e,c as l,v as t,p as s,x as o,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"权变对承诺","description":"","frontmatter":{"title":"权变对承诺","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/discretion-commitment.md","filePath":"econ/discretion-commitment.md","lastUpdated":1789023840000}'),c={name:"econ/discretion-commitment.md"};function h(m,a,B,_,A,f){const i=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="权变对承诺" tabindex="-1">权变对承诺 <a class="header-anchor" href="#权变对承诺" aria-label="Permalink to &quot;权变对承诺&quot;">​</a></h1><div class="epigraph"><p>同一条二次损失，权变每期重解，承诺绑住整条路径；通胀与缺口的轨迹因此不同，并不是目标函数换了。</p><footer>—— Kydland and Prescott, JPE 1977；Barro and Gordon 的通胀偏差；Woodford 在 NK 里的承诺解</footer></div><p><a href="/econ/time-inconsistency">上一课</a>已经证明：事先最优的低通胀，事后常想用意外换缺口；理性预期下权变均衡是高 \\(\\pi\\)、无就业收益。本课的缺口不是再讲一遍诱惑，而是：在已经学过的 NK 损失下，把<strong>权变路径</strong>和<strong>承诺路径</strong>并排写出来——历史依赖、惯性、对成本推动的反应为何不同。神圣巧合是下一课：即便承诺了，稳 \\(\\pi\\) 是否自动稳缺口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把央行目标写成通胀缺口与产出缺口的二次损失，贴现因子与公众相同。约束是动态 IS + NKPC。承诺：在 \\(t=0\\) 选出 \\(\\{i_t\\}\\) 的全路径（或等价的目标规则），受预期一致性约束。权变：每一期把过去当沉没，对给定的 \\(\\mathbb{E}\\pi\\) 再解一次。Kydland–Prescott 说两条一般不重合；本课要看 NK 里不重合表现在哪里。Barro–Gordon 的通胀偏差是无权变约束时的稳态项；前瞻 NKPC 还额外要求：今天的 \\(\\pi\\) 进入昨天的定价，承诺因此更值钱。</p><p>上一课已经把诱惑与通胀偏差钉死。本课不再从「要不要意外通胀」起笔，只比较<strong>同一损失</strong>下两条可计算路径：有没有对过去成本推动的补偿、利率有没有惯性、牺牲比是否改善。没有这条对照，泰勒规则的惯性项没有福利理由，下限上的「更低更久」也没有承诺语言。</p><p><span class="marginnote">「权变」不是乱来。它是每期最优控制，目标函数可以完全是社会福利。差的是约束集：承诺把未来自己的手绑住，从而改变今天的预期。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>权变解是马尔可夫：政策只是当前冲击与当前缺口的函数，没有对过去「通胀欠账」的补偿。成本推动出现时，权变让 \\(\\pi\\) 与 \\(\\tilde{y}\\) 分担，下一期仿佛冲击从未发生。承诺解（Woodford 的无时间视角）让政策对过去的成本推动仍有反应：曾经偏高的 \\(\\pi\\) 要求一段偏低的 \\(\\pi\\) 来补，于是利率有惯性，\\(\\mathbb{E}\\pi\\) 在冲击到来时就更低，当前权衡改善。</p>',9)),(e(),s(E,null,{default:o(()=>[p(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOSS%5B%22%E5%90%8C%E4%B8%80%E4%BA%8C%E6%AC%A1%E6%8D%9F%E5%A4%B1%22%5D%20--%3E%20DISC%5B%22%E6%9D%83%E5%8F%98%EF%BC%9A%E9%80%90%E6%9C%9F%E5%86%8D%E4%BC%98%E5%8C%96%22%5D%0A%20%20LOSS%20--%3E%20COMM%5B%22%E6%89%BF%E8%AF%BA%EF%BC%9A%E5%85%A8%E8%B7%AF%E5%BE%84%22%5D%0A%20%20DISC%20--%3E%20MARK%5B%22%E9%A9%AC%E5%B0%94%E5%8F%AF%E5%A4%AB%EF%BC%8C%E6%97%A0%E5%8E%86%E5%8F%B2%E4%BE%9D%E8%B5%96%22%5D%0A%20%20COMM%20--%3E%20HIST%5B%22%E5%8E%86%E5%8F%B2%E4%BE%9D%E8%B5%96%20%2F%20%E6%83%AF%E6%80%A7%22%5D%0A%20%20HIST%20--%3E%20LOW%5B%22%E5%90%8C%E6%A0%B7%E5%86%B2%E5%87%BB%E4%B8%8B%E6%9B%B4%E5%B0%8F%E7%9A%84%20%CF%80%20%E6%B3%A2%E5%8A%A8%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>泰勒原理约束的是确定性；本课约束的是<strong>哪一条</strong>确定路径。\\(\\phi_\\pi\\gt 1\\) 的简单规则可以逼近承诺，但系数一般含惯性，不是每期重估的最优控制。</p><h3 id="稳态偏差与稳定化偏差" tabindex="-1">稳态偏差与稳定化偏差 <a class="header-anchor" href="#稳态偏差与稳定化偏差" aria-label="Permalink to &quot;稳态偏差与稳定化偏差&quot;">​</a></h3><p>Barro–Gordon 给出正的平均通胀（若目标含推产出超过自然率）。即使去掉这项，成本推动下权变仍过度稳定当前缺口、让 \\(\\pi\\) 多跳——因为未来的补偿未被计入。承诺同时处理两块。Rogoff 保守央行改变的是权变均衡的权重，是制度近似，不是把损失改写成另一套偏好然后假装已承诺。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>NKPC 前瞻：\\(\\mathbb{E}\\pi_{t+1}\\) 进入 \\(\\pi_t\\)。承诺压低整条未来 \\(\\pi\\)，直接改善今天的权衡；权变无法许诺「明天补回来」，公众只信马尔可夫反应，今天的牺牲比更差。动态 IS 同样前瞻：承诺的「更低更久」改变 \\(\\mathbb{E}\\tilde{y}_{t+1}\\)，当前需求一并移动。时间不一致在符号上也可以反过来：零下限上，事后想要紧缩，事先需要把宽松绑住——同一逻辑，工具换成路径。</p><p>卢卡斯批判叠合：把权变当成「最优」，估出来的 Phillips 对准的是高 \\(\\pi\\) 均衡，不是纸上的 \\(\\pi^*\\)。泰勒原理保证确定性；本课保证的是在已确定的系统里走哪一条。\\(\\phi_\\pi\\gt 1\\) 的简单规则若不含历史依赖，更接近权变；加上对过去缺口的补偿，才向承诺靠近。独立央行、通胀目标是制度近似，把再优化的成本写进人事与立法，而不是改写二次损失的代数。</p><p><span class="marginnote">资本税、专利废除是同一结构，上一课已点过。本课对象是名义锚与缺口，因为工具已经是 \\(i\\)。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不校准损失权重，不把沟通措辞当承诺技术的全部——前瞻指引在下限课展开。财政主导可以另起高通胀，不必经过 Phillips 诱惑。也不要把公司金融的资本结构承诺写进来。Kydland–Prescott 原文的专利与洪水保险说明：离开货币，同一结构仍在；本课对象已经换成 \\(i\\) 与 NKPC，不把那些例子再推一遍。</p><p>信誉均衡用重复博弈的触发策略可以逼近承诺，那是<a href="/econ/folk-theorem">无名氏定理</a>换了通胀对象，不是把权变改名为承诺。Rogoff 保守央行改变权变均衡的权重，仍是权变，只是损失里通胀罚得更重。</p><p>后课默认：同一损失下先分清权变路径与承诺路径。下一课问：在基准 NK 里，承诺稳定通胀是否已经自动稳定了福利相关缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>同一损失，权变马尔可夫，承诺历史依赖。</li><li>前瞻 NKPC 使承诺改善当前权衡，不只纠正平均通胀偏差。</li><li>简单泰勒规则是承诺的可检验近似，常需惯性。</li><li>权变可以是「每期最优」而仍差于事先计划。</li><li>下限上符号翻转：事后想紧，事先要把宽松绑住。</li><li>出处：Kydland and Prescott, <em>JPE</em> 1977；Barro–Gordon；Woodford 的承诺解。</li></ul>',13))])}const u=r(c,[["render",h]]);export{P as __pageData,u as default};
